{"cards": [{"node_code": "N_2e90fdb264914fc9", "definition": "研究船舶主动力源及其配套系统的工程领域，涵盖内燃机、汽轮机、燃气轮机、核动力及电力推进等主机原理、结构、性能及运行管理。", "boundary": "本节点聚焦于产生动力的“源”及其直接配套（如燃油、冷却、排气系统）。边界在于区分“动力装置”与“传动/推进”（动力输出后的传递与执行归入兄弟节点）、“辅机”（非主动力源的辅助机械归入辅机节点）。若涉及动力系统的电气控制逻辑，侧重机械本体归入本节点，侧重纯控制算法可关联电气节点。", "includes": ["船舶主机（柴油机、汽轮机等）的结构、热力循环与性能分析", "动力装置的燃油、滑油、冷却、排气等配套系统设计", "动力装置的运行管理、故障诊断与维护技术"], "excludes": ["轴系、齿轮箱等动力传递装置", "螺旋桨、水轮等推进执行机构", "非主动力源的甲板起重、压载泵等辅机"], "sibling_distinctions": [{"other_code": "N_c59de4ea13afe036", "rule": "本节点研究动力源（如发动机），兄弟节点研究动力从源到推进器的传递路径（如轴、齿轮）。"}, {"other_code": "N_8cfcea7919cf4527", "rule": "本节点研究产生推力的能量转换过程，兄弟节点研究将机械能转化为水动力的执行机构（如螺旋桨）。"}, {"other_code": "N_b561fb7a8b0af0cd", "rule": "本节点特指主动力源，兄弟节点涵盖除主动力源外的其他辅助机械（如通风、空调、起重）。"}], "cross_boundary_rule": "若内容涉及“综合电力推进”，侧重发电机组与配电归入本节点或电气节点，侧重电机与推进器接口需视具体侧重，通常动力源部分归本节点。"}, {"node_code": "N_c59de4ea13afe036", "definition": "研究连接动力装置与推进装置之间的机械传动系统，涵盖轴系、齿轮箱、离合器、联轴器及多机并车同步装置的设计、强度与安装。", "boundary": "本节点聚焦于“中间传递”环节，即动力源与推进器之间的机械连接与变速变向。边界在于区分“传动”与“动力”（源）、“推进”（末端执行）。若涉及轴系的电气监测（如振动传感器），侧重机械结构归入本节点，侧重信号处理归入电气。并车装置特指多动力源同步控制机械部分。", "includes": ["船舶轴系（尾轴、中间轴）的结构、强度计算与安装工艺", "齿轮箱、离合器、联轴器等传动部件的设计与选型", "多机并车同步装置的机械结构与工作原理"], "excludes": ["动力主机本身的内部结构", "螺旋桨、导管等直接与水接触的推进部件", "纯电气控制的并车逻辑算法（若侧重软件）"], "sibling_distinctions": [{"other_code": "N_2e90fdb264914fc9", "rule": "本节点研究动力输出后的传递，兄弟节点研究动力产生源。"}, {"other_code": "N_8cfcea7919cf4527", "rule": "本节点研究机械连接与变速，兄弟节点研究最终产生推力的流体机械。"}], "cross_boundary_rule": "若内容涉及“电传动”中的电机与齿轮箱集成，侧重机械传动部分归入本节点，侧重电机本体归入动力或电气节点。"}, {"node_code": "N_8cfcea7919cf4527", "definition": "研究将机械能转化为水动力以驱动船舶运动的装置，涵盖螺旋桨、喷水推进、水轮、导管、侧推器及空气螺旋桨等的设计、性能与优化。", "boundary": "本节点聚焦于“末端执行”机构，即直接与水体或空气作用产生推力的部件。边界在于区分“推进”与“传动”（上游机械连接）、“动力”（能量源）。若涉及推进器的控制（如桨距调节），侧重机械结构归入本节点，侧重控制策略可关联自动化。", "includes": ["螺旋桨（定距、变距）的水动力学设计与强度分析", "喷水推进、水轮、导管等特种推进装置的结构与性能", "侧推器、空气螺旋桨等辅助推进装置的设计与应用"], "excludes": ["驱动推进器的轴系与齿轮箱", "产生动力的主机或电机", "船舶舵系（虽相关但通常归入操纵或单独节点，若树中无舵系节点，需视具体定义，此处暂排除纯舵叶设计）"], "sibling_distinctions": [{"other_code": "N_c59de4ea13afe036", "rule": "本节点研究产生推力的流体机械，兄弟节点研究传递动力的机械轴系。"}, {"other_code": "N_2e90fdb264914fc9", "rule": "本节点研究能量转换的执行端，兄弟节点研究能量产生的源头。"}], "cross_boundary_rule": "若内容涉及“泵喷推进”，侧重泵体与喷口设计归入本节点，若侧重整体系统集成需结合动力与传动节点。"}]}
